effect.shader:
const float PI = 3.14159265;
mat3 mrotX(float a){ float s=sin(a),c=cos(a); return mat3(1.0,0.0,0.0, 0.0,c,-s, 0.0,s,c); }
mat3 mrotY(float a){ float s=sin(a),c=cos(a); return mat3(c,0.0,s, 0.0,1.0,0.0, -s,0.0,c); }
mat3 mrotZ(float a){ float s=sin(a),c=cos(a); return mat3(c,-s,0.0, s,c,0.0, 0.0,0.0,1.0); }
float sdTorus(vec3 p, float R, float r){
    vec2 q=vec2(length(p.xz)-R, p.y);
    return length(q)-r;
}
void main(){
    vec2 uv=(acScreenNorm*2.0-1.0); float asp=acScreenSize.x/acScreenSize.y; uv.x*=asp;
    mat3 R=mrotX(radians(spinX))*mrotY(radians(spinY));
    vec3 ro=vec3(0.0,0.0,-3.0);
    vec3 rd=normalize(vec3(uv,2.0));
    float t=0.0; float hit=-1.0; vec3 pos;
    for(int i=0;i<48;i++){
        pos=ro+rd*t;
        vec3 pr=R*pos;
        float d=sdTorus(pr, 1.0, thickness);
        if(d<0.002){ hit=1.0; break; }
        t+=d;
        if(t>6.0) break;
    }
    if(hit<0.0){ gl_FragColor=vec4(0.0); return; }
    vec3 pr=R*pos;
    vec2 e=vec2(0.002,0.0);
    vec3 nrm=normalize(vec3(
        sdTorus(pr+e.xyy,1.0,thickness)-sdTorus(pr-e.xyy,1.0,thickness),
        sdTorus(pr+e.yxy,1.0,thickness)-sdTorus(pr-e.yxy,1.0,thickness),
        sdTorus(pr+e.yyx,1.0,thickness)-sdTorus(pr-e.yyx,1.0,thickness)));
    float u=0.5+atan(pr.z,pr.x)/(2.0*PI);
    float v=0.5+atan(pr.y, length(pr.xz)-1.0)/(2.0*PI);
    vec4 col=texture2DCv(inputImg.texture, fract(vec2(u,v)));
    vec3 L=normalize(vec3(-0.5,0.7,-0.6));
    float diff=clamp(dot(nrm,L),0.0,1.0);
    float spec=pow(clamp(dot(reflect(rd,nrm),L),0.0,1.0),24.0);
    gl_FragColor=vec4(col.rgb*(0.35+0.8*diff)+spec*0.6, 1.0);
}
